export default function nextOpen({ items, previousState, lastChannelId }) {
  let state = previousState ?? { index: 0, channels: [] };
  if (previousState) {
    if (typeof lastChannelId !== "string" || !lastChannelId)
      throw Error("Slack did not return a conversation ID");
    state = { index: state.index + 1, channels: [...state.channels, lastChannelId] };
  }
  if (state.index > items.length) throw Error("Invalid conversation state");
  return { state, more: state.index < items.length, channels: state.channels };
}

