export default function nextSend({ items, channels, previousState, lastTimestamp }) {
  let state = previousState ?? { index: 0 };
  if (previousState) {
    if (typeof lastTimestamp !== "string" || !lastTimestamp)
      throw Error("Slack did not confirm the previous message");
    state = { index: state.index + 1 };
  }
  if (state.index > items.length || channels.length !== items.length)
    throw Error("Invalid report state");
  const more = state.index < items.length,
    entry = more ? items[state.index] : null;
  return {
    state,
    more,
    channelId: more ? channels[state.index] : "unused",
    attachments: more ? [{ title: "☑️ " + entry.title }] : [{ title: "unused" }],
  };
}
